    return float(math.log(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x > 0 and z is not None and math.isfinite(z):
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    cn = [0.0] * n
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and math.isfinite(nearest[i]) and d <= 1.5 * nearest[i]:
            cn[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    weight = sum(occ)
    return float(sum(occ[i] * cn[i] for i in range(n)) / weight) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    cn = [0.0] * n
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and math.isfinite(nearest[i]) and d <= 1.5 * nearest[i]:
            cn[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * cn[i] for i in range(n)) / weight
    variance = sum(occ[i] * (cn[i] - mean) ** 2 for i in range(n)) / weight
    return float(math.sqrt(max(0.0, variance)) / mean) if mean > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    elements = [t.get('element') for t in sites]
    nearest = [math.inf] * n
    fractions = {}
    for i in range(n):
        e = elements[i]
        fractions[e] = fractions.get(e, 0.0) + occ[i]
    population = sum(occ)
    if population <= 0:
        return 0.0
    baseline = 1.0 - sum((x / population) ** 2 for x in fractions.values())
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    unlike = 0.0
    weight = 0.0
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and math.isfinite(nearest[i]) and d <= 1.5 * nearest[i]:
            w = occ[i] * occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
            weight += w
            if elements[i] != elements[j]:
                unlike += w
    return float(unlike / weight - baseline) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    elements = [t.get('element') for t in sites]
    nearest = [math.inf] * n
    bulk = {}
    for i in range(n):
        e = elements[i]
        bulk[e] = bulk.get(e, 0.0) + occ[i]
    population = sum(occ)
    if population <= 0:
        return 0.0
    entropy = -sum((x / population) * math.log(x / population) for x in bulk.values() if x > 0)
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    local = [{} for i in range(n)]
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and math.isfinite(nearest[i]) and d <= 1.5 * nearest[i]:
            w = occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
            e = elements[j]
            local[i][e] = local[i].get(e, 0.0) + w
    total = 0.0
    weight = 0.0
    for i in range(n):
        z = sum(local[i].values())
        if z > 0:
            h = -sum((x / z) * math.log(x / z) for x in local[i].values() if x > 0)
            total += occ[i] * h
            weight += occ[i]
    return float(total / weight - entropy) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    groups = [[] for i in range(n)]
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and occ[j] > 0:
            groups[i] += [d]
    total = 0.0
    weight = 0.0
    for i in range(n):
        distances = sorted(groups[i])[:17]
        if len(distances) >= 2:
            gap = max(math.log(distances[k + 1] / distances[k]) for k in range(len(distances) - 1))
            total += occ[i] * gap
            weight += occ[i]
    return float(total / weight) if weight > 0 else 0.0

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    if n == 0:
        return 0.0
    props = s.get('element_properties', {})
    en = [props.get(t.get('element'), {}).get('eneg') for t in sites]
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    cn = [0.0] * n
    for b in s.get('neighbors', []):
        i, j, d = b['i'], b['j'], b['distance_A']
        if d is not None and math.isfinite(d) and d > 0 and math.isfinite(nearest[i]) and d <= 1.5 * nearest[i]:
            cn[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    valid = [i for i in range(n) if en[i] is not None and math.isfinite(en[i]) and occ[i] > 0]
    weight = sum(occ[i] for i in valid)
    if weight <= 0:
        return 0.0
    x = sum(occ[i] * en[i] for i in valid) / weight
    y = sum(occ[i] * cn[i] for i in valid) / weight
    vx = sum(occ[i] * (en[i] - x) ** 2 for i in valid)
    vy = sum(occ[i] * (cn[i] - y) ** 2 for i in valid)
    covariance = sum(occ[i] * (en[i] - x) * (cn[i] - y) for i in valid)
    if vx <= 1e-20 or vy <= 1e-20:
        return 0.0
    return float(max(-1.0, min(1.0, covariance / math.sqrt(vx * vy))))
